import hashlib
import heapq
import math
import random

MERSENNE_PRIME_61 = (1 << 61) - 1


def cms_dimensions(epsilon: float, delta: float) -> tuple[int, int]:
    """Compute optimal (width, depth) for error <= epsilon * N with prob >= 1 - delta."""
    if not (0.0 < epsilon < 1.0):
        raise ValueError(f"epsilon must be in (0, 1), got {epsilon}.")
    if not (0.0 < delta < 1.0):
        raise ValueError(f"delta must be in (0, 1), got {delta}.")
    width = math.ceil(math.e / epsilon)
    depth = math.ceil(math.log(1.0 / delta))
    return width, depth


def stable_item_hash64(item: str) -> int:
    """Deterministic 64-bit integer fingerprint (independent of PYTHONHASHSEED)."""
    digest = hashlib.blake2b(str(item).encode("utf-8"), digest_size=8).digest()
    return int.from_bytes(digest, byteorder="little", signed=False)


class CountMinSketch:
    """Sublinear-space approximate streaming frequency tracker (Cormode & Muthukrishnan)."""

    def __init__(self, width: int, depth: int, seed: int = 42) -> None:
        if width < 1 or depth < 1:
            raise ValueError("width and depth must be >= 1.")
        self.width = width
        self.depth = depth
        self.seed = seed
        self.table: list[list[int]] = [[0] * width for _ in range(depth)]
        self.total_count: int = 0
        rng = random.Random(seed)
        # Pairwise-independent 2-universal hash parameters: ((a * x + b) % P) % width
        self._hash_params: list[tuple[int, int]] = [
            (rng.randrange(1, MERSENNE_PRIME_61), rng.randrange(0, MERSENNE_PRIME_61))
            for _ in range(depth)
        ]

    @classmethod
    def from_error_bounds(
        cls,
        epsilon: float,
        delta: float,
        seed: int = 42,
    ) -> "CountMinSketch":
        width, depth = cms_dimensions(epsilon, delta)
        return cls(width=width, depth=depth, seed=seed)

    def _hash(self, item: str, row: int) -> int:
        key = stable_item_hash64(item)
        a, b = self._hash_params[row]
        return ((a * key + b) % MERSENNE_PRIME_61) % self.width

    def merge(self, other: "CountMinSketch") -> "CountMinSketch":
        """Linearly merge two sketches sharing identical (width, depth, seed)."""
        if (self.width, self.depth, self.seed) != (other.width, other.depth, other.seed):
            raise ValueError("Cannot merge sketches with mismatched dimensions or seeds.")
        out = CountMinSketch(self.width, self.depth, self.seed)
        out.total_count = self.total_count + other.total_count
        for r in range(self.depth):
            for c in range(self.width):
                out.table[r][c] = self.table[r][c] + other.table[r][c]
        return out

    def add(self, item: str, count: int = 1) -> None:
        """Increment frequency estimate of `item` by non-negative `count` across all d rows.

        Must validate count >= 0 (negative updates break the never-underestimate
        invariant of standard Count-Min Sketch), increment self.table[r][self._hash(item, r)]
        for each row r in 0..depth-1, and add count to self.total_count.
        """
        # TODO: Validate count >= 0, update all d hash buckets via self._hash(item, r),
        #       and update self.total_count.
        raise NotImplementedError("Implement CountMinSketch.add")

    def estimate(self, item: str) -> int:
        """Return approximate frequency of `item` as the minimum across all d hashed buckets.

        Guarantees estimate(item) >= true_count(item) for non-negative updates.
        """
        # TODO: Query self.table[r][self._hash(item, r)] across all rows r = 0..depth-1
        #       and return the minimum counter value.
        raise NotImplementedError("Implement CountMinSketch.estimate")



class HeavyHitterTracker:
    """Tracks approximate Top-K heavy hitters over a stream using CountMinSketch."""

    def __init__(self, k: int, epsilon: float = 0.01, delta: float = 0.01) -> None:
        self.k = k
        self.cms = CountMinSketch.from_error_bounds(epsilon, delta)
        self._candidates: dict[str, int] = {}

    def observe(self, item: str, count: int = 1) -> None:
        self.cms.add(item, count)
        est = self.cms.estimate(item)
        if item in self._candidates or len(self._candidates) < self.k:
            self._candidates[item] = est
        else:
            min_key = min(self._candidates, key=lambda x: self._candidates[x])
            if est > self._candidates[min_key]:
                del self._candidates[min_key]
                self._candidates[item] = est

    def top_k(self) -> list[tuple[str, int]]:
        return heapq.nlargest(self.k, self._candidates.items(), key=lambda kv: (kv[1], kv[0]))

