        out = CountMinSketch(self.width, self.depth, self.seed)
        out.total_count = self.total_count + other.total_count
        for r in range(self.depth):
            for c in range(self.width):
                out.table[r][c] = self.table[r][c] + other.table[r][c]
        return out

    def add(self, item: str, count: int = 1) -> None:
        """Increment frequency estimate of `item` by non-negative `count` across all d rows."""
        if count < 0:
            raise ValueError(f"CountMinSketch requires non-negative count, got {count}.")
        if count == 0:
            return
        for r in range(self.depth):
            col = self._hash(item, r)
            self.table[r][col] += count
        self.total_count += count

    def estimate(self, item: str) -> int:
        """Return approximate frequency of `item` as the minimum across all d hashed buckets."""
        return min(self.table[r][self._hash(item, r)] for r in range(self.depth))



class HeavyHitterTracker:
    """Tracks approximate Top-K heavy hitters over a stream using CountMinSketch."""

    def __init__(self, k: int, epsilon: float = 0.01, delta: float = 0.01) -> None:
        self.k = k
        self.cms = CountMinSketch.from_error_bounds(epsilon, delta)
        self._candidates: dict[str, int] = {}

    def observe(self, item: str, count: int = 1) -> None:
        self.cms.add(item, count)
        est = self.cms.estimate(item)
        if item in self._candidates or len(self._candidates) < self.k:
            self._candidates[item] = est
        else:
            min_key = min(self._candidates, key=lambda x: self._candidates[x])
            if est > self._candidates[min_key]:
                del self._candidates[min_key]
                self._candidates[item] = est

    def top_k(self) -> list[tuple[str, int]]:
        return heapq.nlargest(self.k, self._candidates.items(), key=lambda kv: (kv[1], kv[0]))


# --- Verification Tests ---
# 1. Exact never-underestimate invariant & PAC error bound on Zipf-like stream
eps, delta = 0.01, 0.01
cms = CountMinSketch.from_error_bounds(epsilon=eps, delta=delta, seed=7)
assert cms.width == math.ceil(math.e / eps) and cms.depth == math.ceil(math.log(1.0 / delta))

true_counts: dict[str, int] = {}
# 3 heavy hitters + 500 long-tail tokens
for tok, freq in [("llm", 800), ("transformer", 500), ("attention", 300)]:
    cms.add(tok, freq)
    true_counts[tok] = freq
for i in range(500):
    tok = f"rare_token_{i}"
    cms.add(tok, 1)
    true_counts[tok] = 1

assert cms.total_count == 2100
max_allowed_err = eps * cms.total_count  # 21.0
for tok, truth in true_counts.items():
    est = cms.estimate(tok)
    assert est >= truth  # HARD INVARIANT: CMS NEVER underestimates!
# Heavy hitters should be well within epsilon * N error
for hh in ("llm", "transformer", "attention"):
    assert cms.estimate(hh) <= true_counts[hh] + max_allowed_err

# 2. Unseen key returns >= 0 (and is very small / often 0)
assert cms.estimate("never_seen_key") >= 0
assert cms.estimate("never_seen_key") <= max_allowed_err

# 3. Distributed linearity: merging two worker sketches equals a single-pass sketch!
s_a = CountMinSketch(width=128, depth=5, seed=11)
s_b = CountMinSketch(width=128, depth=5, seed=11)
s_all = CountMinSketch(width=128, depth=5, seed=11)
for k_item, c in [("a", 10), ("b", 4), ("c", 7)]:
    s_a.add(k_item, c)
    s_all.add(k_item, c)
for k_item, c in [("a", 5), ("d", 12), ("b", 3)]:
    s_b.add(k_item, c)
    s_all.add(k_item, c)
s_merged = s_a.merge(s_b)
assert s_merged.table == s_all.table
assert s_merged.total_count == s_all.total_count
assert s_merged.estimate("a") == s_all.estimate("a") >= 15

# 4. HeavyHitterTracker identifies all 3 true heavy hitters in exact order
tracker = HeavyHitterTracker(k=3, epsilon=0.01, delta=0.01)
for i in range(200):
    tracker.observe(f"noise_{i}", 1)
tracker.observe("gpu", 500)
tracker.observe("cuda", 350)
tracker.observe("triton", 200)
top3_keys = [k for k, _ in tracker.top_k()]
assert top3_keys == ["gpu", "cuda", "triton"]

# 5. Negative count raises ValueError
try:
    cms.add("llm", -5)
    raise AssertionError("Expected ValueError")
except ValueError:
