class TypeaheadService:
    """Production search typeahead wrapper with query normalization."""

    def __init__(self, k: int = 5) -> None:
        self.trie = AutocompleteTrie(k=k)

    @staticmethod
    def normalize(text: str) -> str:
        return " ".join(text.strip().lower().split())

    def record_search(self, raw_query: str, weight: int = 1) -> int:
        norm = self.normalize(raw_query)
        return self.trie.update(norm, freq_delta=weight)

    def suggest(self, raw_prefix: str) -> list[tuple[str, int]]:
        norm = self.normalize(raw_prefix)
        return self.trie.query(norm)
